abhinav_20_23 = {
    'hi': '।।7.20--7.23।। श्री अभिनवगुप्त कहते हैं: विविध कामनाओं से जिनका ज्ञान हरा जा चुका है, वे अपनी-अपनी प्रकृति के अनुसार नियमों का पालन करते हुए अन्य देवताओं की उपासना करते हैं। जो भक्त जिस भी देवता के स्वरूप को श्रद्धा से पूजना चाहता है, उसकी उस श्रद्धा को मैं ही दृढ़ करता हूँ। वह उस श्रद्धा से युक्त होकर उन देवताओं से मेरे द्वारा ही विधान किए गए भोगों को पाता है। परंतु उन अल्पबुद्धि वालों का वह फल अन्तवान् (नाशवान्) होता है; देवताओं को पूजने वाले देवताओं को पाते हैं और मेरे भक्त मुझको ही प्राप्त होते हैं।',
    'en': '7.20--7.23 Sri Abhinavagupta states: Those whose wisdom is carried away by diverse desires resort to other deities, impelled by their own nature. Whichever form of a deity a devotee desires to worship with faith, I make that faith steady. Endowed with that faith, they obtain their desires, which are in truth ordained by Me alone. But finite is the fruit of those of small intellect; worshippers of deities go to deities, but My devotees come unto Me.',
    'be': '৭.২০--৭.২৩ শ্রী অভিনবগুপ্ত বলেছেন: নানা কামনা থেকে যাদের জ্ঞান হরণ করা হয়ে গেছে, তারা নিজের-নিজের প্রকৃতির অনুসারে নিয়মের পালন করতে করতে অন্য দেবতাদের উপাসনা করে। যে ভক্ত যে দেবতার রূপকে শ্রদ্ধায় পূজো করতে চায়, তার সেই শ্রদ্ধাকে আমিই দৃঢ় করি। সে সেই শ্রদ্ধায় যুক্ত হয়ে সেই দেবতাদের থেকে আমার দ্বারাই বিধান করা ভোগ পায়। কিন্তু সেই অল্পবুদ্ধিদের সেই ফল অন্তবান (নাশবান) হয়; দেবতাদের পূজো করা দেবতাকে পায় এবং আমার ভক্ত আমাকেই প্রাপ্ত হয়।',
    'ka': '೭.೨೦--೭.೨೩ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ವಿಭಿನ್ನ ಕಾಮನೆಗಳಿಂದ ಯಾರ ಜ್ಞಾನವು ಅಪಹರಿಸಲ್ಪಟ್ಟಿದೆಯೋ, ಅವರು ತಮ್ಮ ತಮ್ಮ ಪ್ರಕೃತಿಗೆ ಅನುಗುಣವಾಗಿ ನಿಯಮಗಳನ್ನು ಪಾಲಿಸುತ್ತಾ ಅನ್ಯ ದೇವತೆಗಳನ್ನು ಉಪಾಸನೆ ಮಾಡುತ್ತಾರೆ. ಯಾವ ಭಕ್ತನು ಯಾವ ದೇವತೆಯ ಸ್ವರೂಪವನ್ನು ಶ್ರದ್ಧೆಯಿಂದ ಪೂಜಿಸಲು ಬಯಸುತ್ತಾನೋ, ಆತನ ಆ ಶ್ರದ್ಧೆಯನ್ನು ನಾನೇ ದೃಢಗೊಳಿಸುತ್ತೇನೆ. ಆತನು ಆ ಶ್ರದ್ಧೆಯಿಂದ ಯುಕ್ತನಾಗಿ ಆ ದೇವತೆಗಳಿಂದ ನನ್ನಿಂದಲೇ ವಿಧಿಸಲ್ಪಟ್ಟ ಭೋಗಗಳನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಆದರೆ ಅಂತಹ ಅಲ್ಪಬುದ್ಧಿಯುಳ್ಳವರ ಆ ಫಲವು ನಾಶವಾಗತಕ್ಕದ್ದಾಗಿದೆ; ದೇವತೆಗಳನ್ನು ಪೂಜಿಸುವವರು ದೇವತೆಗಳನ್ನು ಹೊಂದುತ್ತಾರೆ ಹಾಗೂ ನನ್ನ ಭಕ್ತರು ನನ್ನನ್ನೇ ಪಡೆಯುತ್ತಾರೆ'
}

abhinav_24_25 = {
    'hi': '।।7.24--7.25।। श्री अभिनवगुप्त कहते हैं: बुद्धिहीन पुरुष मेरे अनुत्तम और अविनाशी परम भाव को न जानते हुए मुझे अव्यक्त से व्यक्त (मनुष्य-शरीरधारी) हुआ मानते हैं। मैं अपनी योगमाया से ढका हुआ होने के कारण सबके सम्मुख प्रत्यक्ष नहीं होता; इसलिए यह मूढ़ जगत् मुझे अजन्मा और अविनाशी परमेश्वर को नहीं पहचान पाता।',
    'en': '7.24--7.25 Sri Abhinavagupta states: Unintelligent men, not knowing My supreme, unexcelled, imperishable state, consider Me, the Unmanifest, to have assumed human birth. Veiled by My divine Yoga-Maya, I am not revealed to all; hence this deluded world fails to comprehend Me, the Unborn and Imperishable Lord.',
    'be': '৭.২৪--৭.২৫ শ্রী অভিনবগুপ্ত বলেছেন: বুদ্ধিহীন পুরুষ আমার অনুত্তম ও অবিনাশী পরম ভাবকে না জেনে আমাকে অব্যক্ত থেকে ব্যক্ত (মনুষ্য-শরীরধারী) হওয়া মানে। আমি আমার যোগমায়া থেকে ঢাকা হওয়ার কারণে সবার সম্মুখে প্রত্যক্ষ হই না; তাই এই মূঢ় জগৎ আমাকে অজন্মা ও অবিনাশী পরমেশ্বরকে চিনতে পারে না।',
    'ka': '೭.೨೪--೭.೨೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಬುದ್ಧಿಹೀನ ಪುರುಷರು ನನ್ನ ಅತ್ಯುತ್ತಮವೂ ಅವಿನಾಶಿಯೂ ಆದ ಪರಮಭಾವವನ್ನು ಅರಿಯದೆ ನನ್ನನ್ನು ಅವ್ಯಕ್ತನಾಗಿದ್ದು ವ್ಯಕ್ತನಾದವನೆಂದು (ಮನುಷ್ಯಶರೀರ ಧರಿಸಿದವ) ಭಾವಿಸುತ್ತಾರೆ. ನಾನು ನನ್ನ ಯೋಗಮಾಯೆಯಿಂದ ಮರೆಮಾಡಲ್ಪಟ್ಟಿರುವುದರಿಂದ ಎಲ್ಲರ ಕಣ್ಣೆದುರು ಪ್ರತ್ಯಕ್ಷನಾಗುವುದಿಲ್ಲ; ಆದ್ದರಿಂದ ಈ ಮೂಢ ಜಗತ್ತು ಅಜನ್ಮನೂ ಅವಿನಾಶಿಯೂ ಆದ ಪರಮೇಶ್ವರನಾದ ನನ್ನನ್ನು ಗುರುತಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ'
}

